// This file is generated by frontend/scripts/write-config.js during the Vercel build.
// It is safe to expose these public frontend values. Do not put backend secrets here.
(function () {
  const LOCAL_API_URL = 'http://localhost:5000';
  const PRODUCTION_API_URL = window.TYNA_BACKEND_URL || "" || location.origin;
  const isLocal =
    location.hostname === 'localhost' ||
    location.hostname === '127.0.0.1';

  window.TYNA_API_URL = isLocal
    ? LOCAL_API_URL
    : String(PRODUCTION_API_URL).replace(/\/$/, '');

  window.TYNA_GOOGLE_CLIENT_ID = window.TYNA_GOOGLE_CLIENT_ID || "";
  window.TYNA_PAYSTACK_PUBLIC_KEY = window.TYNA_PAYSTACK_PUBLIC_KEY || "";
  window.TYNA_PUBLIC_WHATSAPP_NUMBER = window.TYNA_PUBLIC_WHATSAPP_NUMBER || "";
  window.TYNA_PUBLIC_WHATSAPP_INTERNATIONAL = window.TYNA_PUBLIC_WHATSAPP_INTERNATIONAL || "";
  window.TYNA_USD_NGN_RATE = Number(window.TYNA_USD_NGN_RATE || "");
  window.TYNA_ADSENSE_CLIENT_ID = window.TYNA_ADSENSE_CLIENT_ID || "";
})();
